            aIngress = aIngress + (aOrbiterD ^ RotL64(aOrbiterC, 51U));
            aIngress = aIngress + (aOrbiterI ^ RotL64(aOrbiterG, 27U));
            aIngress = aIngress + RotL64(aOrbiterJ, 41U);
            aIngress = TwistMix64::DiffuseB((aIngress + aScatter));
            //
            aWandererI = aWandererI + ((((RotL64(aScatter, 5U) + aOrbiterH) + RotL64(aOrbiterD, 41U)) + RotL64(aCarry, 23U)) + aTwistWandererUpdateSaltE[((aIndex + 16U)) & S_SALT1]);
