            //
            aOrbiterI = ((aOrbiterI + aOrbiterH) + 0x732451A6A5879A77ULL) + aTwistOrbiterUpdateSaltD[((aIndex + 117U)) & S_SALT1];
            aOrbiterE = (aOrbiterE ^ aOrbiterI) ^ 0x8FD8D0A10FBC5E28ULL;
            aOrbiterE = RotL64((aOrbiterE * 0x920E8D84E6DB04A3ULL), 23U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterB) + 0xAEBEE4B033C2B455ULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterE) ^ 0xFB2DB931F4DFC1DCULL;
            aOrbiterA = RotL64((aOrbiterA * 0x8487B936F209C6BBULL), 39U);
