            //
            aOrbiterG = (aOrbiterG + aOrbiterI) + 0x79B58F8A64925E43ULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterG) ^ 0xA1EDD5550438FD43ULL;
            aOrbiterC = RotL64((aOrbiterC * 0x355EC673CA1F2415ULL), 57U);
