            aOrbiterG = (aWandererA + RotL64(aIngress, 19U)) + 0xD01E7F7E9AE78F37ULL;
            aOrbiterJ = ((aWandererH + RotL64(aCross, 48U)) + RotL64(aCarry, 39U)) + 0x784711303B2716CCULL;
