            aOrbiterG = ((aWandererK + RotL64(aIngress, 47U)) + RotL64(aCarry, 37U)) + 0xB17DDE3E3083744BULL;
            aOrbiterE = ((aWandererI + RotL64(aPrevious, 13U)) + RotL64(aCarry, 19U)) + 0x843B239F0C74D704ULL;
