            aScatter = TwistMix64::DiffuseC((aScatter ^ aKeyRotateBDomainWordScatter));
            //
            aOrbiterB = ((aWandererE + RotL64(aCross, 11U)) + RotL64(aCarry, 57U)) + 0x6C8C6C46C1694537ULL;
            aOrbiterH = (aWandererF + RotL64(aIngress, 35U)) + 0x4A3D0D68D5324859ULL;
            aOrbiterI = (aWandererJ + RotL64(aScatter, 4U)) + 0x147582970AAB75CEULL;
            aOrbiterC = ((aWandererB + RotL64(aPrevious, 23U)) + 0x67048CE852C157D1ULL) + aKeyRotateBOrbiterAssignSaltC[((aIndex + 223U)) & S_SALT1];
            aOrbiterA = (((aWandererI + RotL64(aIngress, 41U)) + RotL64(aCarry, 35U)) + 0x930C7B3727632752ULL) + aKeyRotateBOrbiterAssignSaltE[(((255U - aIndex) + 123U)) & S_SALT1];
            aOrbiterJ = (aWandererH + RotL64(aCross, 29U)) + 0x27B45344E9D7C987ULL;
            aOrbiterG = ((aWandererA + RotL64(aScatter, 57U)) + RotL64(aCarry, 13U)) + 0x569CFE1E0380DC58ULL;
            //
            aOrbiterB = (aOrbiterB + aOrbiterH) + 0x3CAAEBA86966D82DULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterB) ^ 0x1F3BB5B5B20B964DULL;
